use anyhow::{Result,bail,anyhow};use std::{path::{Path,PathBuf},ffi::OsString,time::Duration};
use windows_service::{service::{ServiceAccess,ServiceInfo,ServiceType,ServiceStartType,ServiceErrorControl,ServiceControl,ServiceControlAccept,ServiceExitCode,ServiceState,ServiceStatus},service_manager::{ServiceManager,ServiceManagerAccess},service_control_handler::{self,ServiceControlHandlerResult}};
const SERVICE:&str="HostifyEngine";
fn xml(s:&str)->String{s.replace('&',"&amp;").replace('<',"&lt;").replace('>',"&gt;").replace('"',"&quot;").replace('\'',"&apos;")}
fn hidden(exe:&str)->std::process::Command{use std::os::windows::process::CommandExt;let mut c=std::process::Command::new(exe);c.creation_flags(0x08000000);c}
pub fn task(install:bool,root:&Path)->Result<()>{let sid=crate::windows::sid()?;let name=format!("HostifyEngine-{sid}");let mut command=hidden("schtasks.exe");if install{let exe=std::env::current_exe()?;std::fs::create_dir_all(root.join("run"))?;let path=root.join("run/logon-task.xml");let definition=format!(r#"<?xml version="1.0" encoding="UTF-16"?><Task version="1.2" xmlns="http://schemas.microsoft.com/windows/2004/02/mit/task"><Triggers><LogonTrigger><Enabled>true</Enabled><UserId>{}</UserId></LogonTrigger></Triggers><Principals><Principal id="Author"><UserId>{}</UserId><LogonType>InteractiveToken</LogonType><RunLevel>LeastPrivilege</RunLevel></Principal></Principals><Settings><MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy><DisallowStartIfOnBatteries>false</DisallowStartIfOnBatteries><StopIfGoingOnBatteries>false</StopIfGoingOnBatteries><ExecutionTimeLimit>PT0S</ExecutionTimeLimit><RestartOnFailure><Interval>PT1M</Interval><Count>10</Count></RestartOnFailure></Settings><Actions Context="Author"><Exec><Command>{}</Command><Arguments>--data-dir &quot;{}&quot;</Arguments></Exec></Actions></Task>"#,xml(&sid),xml(&sid),xml(&exe.to_string_lossy()),xml(&root.to_string_lossy()));let data=std::iter::once(0xfeffu16).chain(definition.encode_utf16()).flat_map(u16::to_le_bytes).collect::<Vec<_>>();std::fs::write(&path,data)?;command.args(["/Create","/TN",&name,"/XML"]).arg(&path).arg("/F");}else{command.args(["/Delete","/TN",&name,"/F"]);}let output=command.output()?;if !output.status.success(){bail!("Scheduled Task update failed: {}",String::from_utf8_lossy(&output.stderr))}Ok(())}
pub fn service_install(install:bool,root:&Path)->Result<()>{let manager=ServiceManager::local_computer(None::<&str>,ServiceManagerAccess::CONNECT|if install{ServiceManagerAccess::CREATE_SERVICE}else{ServiceManagerAccess::empty()})?;if install{let sid=crate::windows::sid()?;manager.create_service(&ServiceInfo{name:OsString::from(SERVICE),display_name:OsString::from("Hostify Engine"),service_type:ServiceType::OWN_PROCESS,start_type:ServiceStartType::AutoStart,error_control:ServiceErrorControl::Normal,executable_path:std::env::current_exe()?,launch_arguments:vec!["--service".into(),"--data-dir".into(),root.as_os_str().to_owned(),"--owner-sid".into(),sid.into()],dependencies:vec![],account_name:None,account_password:None},ServiceAccess::START|ServiceAccess::QUERY_STATUS)?.start::<&str>(&[])?;}else{let service=manager.open_service(SERVICE,ServiceAccess::DELETE|ServiceAccess::STOP|ServiceAccess::QUERY_STATUS)?;if service.query_status()?.current_state!=ServiceState::Stopped{service.stop()?;}service.delete()?;}Ok(())}
pub fn data_dir()->Result<PathBuf>{let args=std::env::args_os().collect::<Vec<_>>();if let Some(i)=args.iter().position(|a|a=="--data-dir"){return args.get(i+1).map(PathBuf::from).ok_or_else(||anyhow!("--data-dir requires a path"))}if let Some(path)=std::env::var_os("HOSTIFY_DATA_DIR"){return Ok(path.into())}Ok(hostify_core::paths::HostifyPaths::discover()?.root)}
pub async fn run(root:PathBuf,service:bool,mut shutdown:tokio::sync::watch::Receiver<bool>)->Result<()>{let _instance=crate::windows::single_instance()?;let store=crate::state::Store::open(root)?;let supervisor=crate::supervisor::Supervisor::new(store.clone())?;let engine=crate::state::Engine::production(store.clone(),supervisor.clone(),service);engine.startup().await?;store.activity("info",None,"Hostify engine started")?;let name=crate::windows::pipe_name()?;let server=crate::pipe::serve(name,engine.clone(),shutdown.clone());tokio::pin!(server);let result=tokio::select!{result=&mut server=>result.map_err(anyhow::Error::from),_=shutdown.changed()=>Ok(())};engine.shutdown().await;supervisor.shutdown().await;store.activity("info",None,"Hostify engine stopped")?;result}
static CONSOLE_STOP:std::sync::OnceLock<tokio::sync::watch::Sender<bool>>=std::sync::OnceLock::new();
static CONSOLE_DONE:std::sync::atomic::AtomicBool=std::sync::atomic::AtomicBool::new(false);
unsafe extern "system" fn console_handler(event:u32)->i32{if [0,1,2,5,6].contains(&event){if let Some(tx)=CONSOLE_STOP.get(){let _=tx.send(true);}if [2,5,6].contains(&event){for _ in 0..40{if CONSOLE_DONE.load(std::sync::atomic::Ordering::SeqCst){break}std::thread::sleep(Duration::from_millis(100));}}1}else{0}}
pub fn main_entry()->Result<()>{let args=std::env::args().collect::<Vec<_>>();if let Some(i)=args.iter().position(|a|a=="--owner-sid"){crate::windows::set_owner(args.get(i+1).ok_or_else(||anyhow!("Missing owner SID"))?)?;}let root=std::path::absolute(data_dir()?)?;match args.get(1).map(String::as_str){Some("install-task")=>return task(true,&root),Some("uninstall-task")=>return task(false,&root),Some("install-service")=>return service_install(true,&root),Some("uninstall-service")=>return service_install(false,&root),_=>{}}if args.iter().any(|a|a=="--service"){return windows_service::service_dispatcher::start(SERVICE,ffi_service_main).map_err(Into::into)}let rt=tokio::runtime::Runtime::new()?;rt.block_on(async{if args.get(1).map(String::as_str)==Some("status"){use tokio::io::{AsyncWriteExt,AsyncBufReadExt};let mut pipe=tokio::net::windows::named_pipe::ClientOptions::new().open(crate::windows::pipe_name()?)?;pipe.write_all(b"{\"id\":1,\"method\":\"engine_status\",\"params\":{}}\n").await?;let mut response=String::new();tokio::time::timeout(Duration::from_secs(10),tokio::io::BufReader::new(pipe).read_line(&mut response)).await??;println!("{}",response.trim());return Ok(())}let (tx,rx)=tokio::sync::watch::channel(false);let _=CONSOLE_STOP.set(tx);unsafe{if windows_sys::Win32::System::Console::SetConsoleCtrlHandler(Some(console_handler),1)==0{return Err(std::io::Error::last_os_error().into())}}let result=run(root,false,rx).await;CONSOLE_DONE.store(true,std::sync::atomic::Ordering::SeqCst);result})}
windows_service::define_windows_service!(ffi_service_main,service_main);
fn service_main(_:Vec<OsString>){let result=run_service();if let Err(e)=result{if let Ok(root)=data_dir(){let _=std::fs::create_dir_all(root.join("logs"));let _=crate::supervisor::append_log(&root.join("logs/engine.log"),&format!("Service failed: {e}"));}}}
fn run_service()->Result<()>{let (tx,rx)=tokio::sync::watch::channel(false);let handle=service_control_handler::register(SERVICE,move|event|match event{ServiceControl::Stop|ServiceControl::Shutdown=>{let _=tx.send(true);ServiceControlHandlerResult::NoError},ServiceControl::Interrogate=>ServiceControlHandlerResult::NoError,_=>ServiceControlHandlerResult::NotImplemented})?;let report=|state,code|handle.set_service_status(ServiceStatus{service_type:ServiceType::OWN_PROCESS,current_state:state,controls_accepted:if state==ServiceState::Running{ServiceControlAccept::STOP|ServiceControlAccept::SHUTDOWN}else{ServiceControlAccept::empty()},exit_code:ServiceExitCode::Win32(code),checkpoint:0,wait_hint:Duration::from_secs(10),process_id:None});report(ServiceState::Running,0)?;let result=tokio::runtime::Runtime::new()?.block_on(run(std::path::absolute(data_dir()?)?,true,rx));report(ServiceState::Stopped,if result.is_ok(){0}else{1})?;result}
#[cfg(test)]mod tests{#[test]fn xml_escape(){assert_eq!(super::xml("a&<\"'"),"a&amp;&lt;&quot;&apos;");}}


